@@ -433,2 +433,6 @@
-  // SHA-3
-  if (UseSHA3Intrinsics) {
+  // SHA-3 uses scalar Zbb instructions.
+  if (UseSHA && UseZbb) {
+    if (FLAG_IS_DEFAULT(UseSHA3Intrinsics)) {
+      FLAG_SET_DEFAULT(UseSHA3Intrinsics, true);
+    }
+  } else if (UseSHA3Intrinsics) {
